import{_ as o,C as n,o as s,c as d,j as e,a,b as h,w as i,E as l,a3 as c,a2 as p}from"./chunks/framework.DaUU7NnF.js";const f=JSON.parse('{"title":"Trust and Boundaries","description":"Authentication, authorization, and trust boundaries in hookshot","frontmatter":{"title":"Trust and Boundaries","description":"Authentication, authorization, and trust boundaries in hookshot","audience":["operator","architect","contributor"]},"headers":[],"relativePath":"understand/trust-and-boundaries.md","filePath":"understand/trust-and-boundaries.md","lastUpdated":1775242895000}'),k={name:"understand/trust-and-boundaries.md"};function u(b,t,m,g,y,A){const r=n("Mermaid");return s(),d("div",null,[t[1]||(t[1]=e("h1",{id:"trust-and-boundaries",tabindex:"-1"},[a("Trust and Boundaries "),e("a",{class:"header-anchor",href:"#trust-and-boundaries","aria-label":'Permalink to "Trust and Boundaries"'},"​")],-1)),t[2]||(t[2]=e("p",null,"Hookshot sits at the intersection of two trust domains: Matrix and external services. Understanding where trust boundaries are — and how credentials flow — is essential for secure deployment.",-1)),t[3]||(t[3]=e("h2",{id:"trust-boundary-diagram",tabindex:"-1"},[a("Trust boundary diagram "),e("a",{class:"header-anchor",href:"#trust-boundary-diagram","aria-label":'Permalink to "Trust boundary diagram"'},"​")],-1)),(s(),h(c,null,{default:i(()=>[l(r,{id:"mermaid-9",class:"mermaid",graph:"graph%20TB%0A%20%20%20%20subgraph%20Matrix%5B%22Matrix%20Trust%20Domain%22%5D%0A%20%20%20%20%20%20%20%20HS%5B%22Homeserver%3Cbr%2F%3E(Synapse%2FDendrite)%22%5D%0A%20%20%20%20%20%20%20%20AS%5B%22Appservice%20Registration%3Cbr%2F%3E(hs_token%2C%20as_token)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Hookshot%5B%22Hookshot%20Process%22%5D%0A%20%20%20%20%20%20%20%20CRED%5B%22Token%20Store%3Cbr%2F%3E(encrypted%20PEM)%22%5D%0A%20%20%20%20%20%20%20%20PERM%5B%22Permission%20System%3Cbr%2F%3E(Rust%20NAPI)%22%5D%0A%20%20%20%20%20%20%20%20SAND%5B%22QuickJS%20Sandbox%3Cbr%2F%3E(transformation%20functions)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20External%5B%22External%20Service%20Trust%20Domains%22%5D%0A%20%20%20%20%20%20%20%20GH%5B%22GitHub%3Cbr%2F%3E(App%20private%20key%2C%20user%20OAuth%20tokens)%22%5D%0A%20%20%20%20%20%20%20%20GL%5B%22GitLab%3Cbr%2F%3E(access%20tokens)%22%5D%0A%20%20%20%20%20%20%20%20JI%5B%22JIRA%3Cbr%2F%3E(OAuth%20tokens)%22%5D%0A%20%20%20%20%20%20%20%20OP%5B%22OpenProject%3Cbr%2F%3E(OAuth%20tokens)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20HS%20%3C--%3E%7Cappservice%20protocol%3Cbr%2F%3E(hs_token%2Fas_token)%7C%20AS%0A%20%20%20%20AS%20%3C--%3E%20Hookshot%0A%20%20%20%20CRED%20--%3E%7Cinstallation%20tokens%7C%20GH%0A%20%20%20%20CRED%20--%3E%7Cbearer%20tokens%7C%20GL%0A%20%20%20%20CRED%20--%3E%7COAuth%20tokens%7C%20JI%0A%20%20%20%20CRED%20--%3E%7COAuth%20tokens%7C%20OP%0A%0A%20%20%20%20style%20Matrix%20fill%3A%23e3f2fd%2Cstroke%3A%231976D2%0A%20%20%20%20style%20Hookshot%20fill%3A%23e8f5e9%2Cstroke%3A%23388E3C%0A%20%20%20%20style%20External%20fill%3A%23fff3e0%2Cstroke%3A%23F57C00%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=p(`<h2 id="matrix-side-appservice-authentication" tabindex="-1">Matrix side: Appservice authentication <a class="header-anchor" href="#matrix-side-appservice-authentication" aria-label="Permalink to &quot;Matrix side: Appservice authentication&quot;">​</a></h2><p>Hookshot registers with the homeserver as an <strong>application service</strong>. This is a privileged relationship:</p><table tabindex="0"><thead><tr><th>Credential</th><th>Purpose</th><th>Risk if compromised</th></tr></thead><tbody><tr><td><code>as_token</code></td><td>Hookshot authenticates to homeserver</td><td>Full access to impersonate bot users</td></tr><tr><td><code>hs_token</code></td><td>Homeserver authenticates to hookshot</td><td>Can send fake events to hookshot</td></tr></tbody></table><p>These tokens are in <code>registration.yaml</code>. Both hookshot and the homeserver must have copies.</p><p>The appservice can:</p><ul><li>Send messages as bot users (<code>@hookshot:domain</code>, <code>@_github_*:domain</code>, etc.)</li><li>Read events in rooms where the bot is a member</li><li>Create and manage rooms</li><li>Cannot read events in rooms where the bot is not a member</li></ul><h2 id="external-service-side-per-service-auth" tabindex="-1">External service side: Per-service auth <a class="header-anchor" href="#external-service-side-per-service-auth" aria-label="Permalink to &quot;External service side: Per-service auth&quot;">​</a></h2><p>Each external service uses its own authentication model:</p><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Credential</th><th>Type</th><th>Stored where</th><th>Scope</th></tr></thead><tbody><tr><td>App private key</td><td>RSA PEM file</td><td>Filesystem</td><td>Instance-wide: all webhook delivery + API access</td></tr><tr><td>Webhook secret</td><td>HMAC key</td><td>config.yml</td><td>Instance-wide: webhook signature verification</td></tr><tr><td>User OAuth tokens</td><td>Bearer tokens</td><td>Token store (encrypted)</td><td>Per-user: actions under user&#39;s identity</td></tr><tr><td>Personal access tokens</td><td>API tokens</td><td>Token store (encrypted)</td><td>Per-user: alternative to OAuth</td></tr></tbody></table><p>The GitHub App is the most privileged credential. It can read/write issues, PRs, and discussions on every repo where the App is installed.</p><h3 id="gitlab" tabindex="-1">GitLab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;GitLab&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Credential</th><th>Type</th><th>Stored where</th><th>Scope</th></tr></thead><tbody><tr><td>Instance token</td><td>Personal access token</td><td>Account data (per-user)</td><td>Per-user: API access to their GitLab</td></tr></tbody></table><p>No instance-wide credential. Each user provides their own token.</p><h3 id="jira" tabindex="-1">JIRA <a class="header-anchor" href="#jira" aria-label="Permalink to &quot;JIRA&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Credential</th><th>Type</th><th>Stored where</th><th>Scope</th></tr></thead><tbody><tr><td>OAuth 2.0 tokens (Cloud)</td><td>Bearer + refresh</td><td>Token store (encrypted)</td><td>Per-user</td></tr><tr><td>OAuth 1.0 tokens (Server)</td><td>RSA-signed</td><td>Token store (encrypted)</td><td>Per-user</td></tr></tbody></table><h3 id="openproject" tabindex="-1">OpenProject <a class="header-anchor" href="#openproject" aria-label="Permalink to &quot;OpenProject&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Credential</th><th>Type</th><th>Stored where</th><th>Scope</th></tr></thead><tbody><tr><td>OAuth 2.0 tokens</td><td>Bearer + refresh</td><td>Token store (encrypted)</td><td>Per-user</td></tr></tbody></table><h2 id="token-store" tabindex="-1">Token store <a class="header-anchor" href="#token-store" aria-label="Permalink to &quot;Token store&quot;">​</a></h2><p>User credentials (OAuth tokens, personal access tokens) are stored in an encrypted file on disk.</p><ul><li><strong>Encryption:</strong> RSA key from <code>passFile</code> in config</li><li><strong>Location:</strong> Configured via <code>passFile</code> path</li><li><strong>Format:</strong> Encrypted JSON</li></ul><p>The <code>passFile</code> RSA key is the master secret. If compromised, all stored tokens are exposed.</p><h2 id="permission-system" tabindex="-1">Permission system <a class="header-anchor" href="#permission-system" aria-label="Permalink to &quot;Permission system&quot;">​</a></h2><p>Hookshot&#39;s permission system controls who can do what. It runs in Rust via NAPI for performance.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">permissions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # All users on this domain</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # All services</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # Full access</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@user:example.com&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Specific user</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">github</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">commands</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Can run bot commands only</span></span></code></pre></div><p>Permission levels (ascending): <code>login</code> &lt; <code>notifications</code> &lt; <code>commands</code> &lt; <code>manageConnections</code> &lt; <code>admin</code></p><h3 id="what-each-level-allows" tabindex="-1">What each level allows <a class="header-anchor" href="#what-each-level-allows" aria-label="Permalink to &quot;What each level allows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Can do</th></tr></thead><tbody><tr><td><code>login</code></td><td>Authenticate with external services</td></tr><tr><td><code>notifications</code></td><td>Receive notifications</td></tr><tr><td><code>commands</code></td><td>Run bot commands (create issues, etc.)</td></tr><tr><td><code>manageConnections</code></td><td>Create and remove connections</td></tr><tr><td><code>admin</code></td><td>Full administrative access</td></tr></tbody></table><h2 id="webhook-verification" tabindex="-1">Webhook verification <a class="header-anchor" href="#webhook-verification" aria-label="Permalink to &quot;Webhook verification&quot;">​</a></h2><p>Inbound webhooks are verified differently per service:</p><table tabindex="0"><thead><tr><th>Service</th><th>Method</th><th>What hookshot checks</th></tr></thead><tbody><tr><td>GitHub</td><td>HMAC-SHA256</td><td><code>x-hub-signature-256</code> header against configured secret</td></tr><tr><td>GitLab</td><td>Secret token</td><td><code>X-Gitlab-Token</code> header against configured secret</td></tr><tr><td>JIRA</td><td>—</td><td>Payload structure validation</td></tr><tr><td>Generic webhooks</td><td>None</td><td>URL contains unique UUID (knowledge = access)</td></tr><tr><td>Figma</td><td>—</td><td>Payload structure validation</td></tr></tbody></table><p>Generic webhooks have <strong>no signature verification</strong>. The unique UUID in the URL is the only protection. Treat webhook URLs as secrets.</p><h2 id="transformation-function-sandbox" tabindex="-1">Transformation function sandbox <a class="header-anchor" href="#transformation-function-sandbox" aria-label="Permalink to &quot;Transformation function sandbox&quot;">​</a></h2><p>User-supplied JavaScript transformation functions run in a <strong>QuickJS sandbox</strong> (WebAssembly). This is a security boundary:</p><table tabindex="0"><thead><tr><th>Allowed</th><th>Blocked</th></tr></thead><tbody><tr><td>Read webhook payload (<code>data</code> variable)</td><td>Network access</td></tr><tr><td>String manipulation</td><td>Filesystem access</td></tr><tr><td>JSON operations</td><td>Module imports</td></tr><tr><td>Return formatted message</td><td>Process spawning</td></tr></tbody></table><p>Functions are killed after 500ms.</p><h2 id="what-to-protect" tabindex="-1">What to protect <a class="header-anchor" href="#what-to-protect" aria-label="Permalink to &quot;What to protect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Asset</th><th>Risk</th><th>Mitigation</th></tr></thead><tbody><tr><td><code>registration.yaml</code> (as_token, hs_token)</td><td>Full bot impersonation</td><td>File permissions, don&#39;t commit to git</td></tr><tr><td><code>passFile</code> (RSA key)</td><td>All stored tokens exposed</td><td>File permissions, don&#39;t commit to git</td></tr><tr><td>GitHub App private key</td><td>Full API access to installed repos</td><td>File permissions, rotate periodically</td></tr><tr><td>Webhook secrets</td><td>Spoofed webhook events</td><td>Strong random values, keep in config only</td></tr><tr><td>Generic webhook URLs</td><td>Unauthorized message injection</td><td>Treat as secrets, use expiration dates</td></tr><tr><td>config.yml</td><td>Contains secrets in plaintext</td><td>File permissions, don&#39;t commit to git</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./what-is-hookshot">What is Hookshot</a> — System overview</li><li><a href="./integration-model">Integration Model</a> — How integrations work</li><li><a href="./../integrations/github">GitHub Integration</a> — GitHub auth details</li><li><a href="./../guides/operator/hardening">Operator: Hardening</a> — Security configuration</li><li><a href="https://spec.matrix.org/latest/application-service-api/" target="_blank" rel="noreferrer">Matrix Spec: Application Service API</a></li></ul>`,40))])}const v=o(k,[["render",u]]);export{f as __pageData,v as default};
